proof fn lemma_prefix_sum_eq_sum_first_n(s: Seq<i32>, n: int)
    requires
        0 <= n <= s.len(),
    ensures
        prefix_sum(s.subrange(0, n)) == sum(first_n(s, n)),
    decreases n,
{
    if n == 0 {
        assert(s.subrange(0, 0).len() == 0);
        assert(first_n(s, 0).len() == 0);
        assert(prefix_sum(s.subrange(0, 0)) == 0);
        assert(sum(first_n(s, 0)) == 0);
    } else {
        lemma_prefix_sum_eq_sum_first_n(s, n - 1);
        let p = s.subrange(0, n);
        let q1 = first_n(s, n - 1);
        let q2 = first_n(s, n);
        assert(p.len() == n);
        assert(p.drop_last() =~= s.subrange(0, n - 1));
        assert(q2.len() == n);
        assert(q1.len() == n - 1);
        assert(q2.drop_last() =~= q1);
        assert(q2.last() == s[n - 1] as int);
        assert(p.last() == s[n - 1]);
        lemma_sum_equals_sum_other_way(q2);
        lemma_sum_equals_sum_other_way(q1);
        assert(sum_other_way(q2) == q2.last() + sum_other_way(q2.drop_last()));
        assert(prefix_sum(p) == prefix_sum(p.drop_last()) + p.last() as int);
    }
}

fn main() {}
    assert forall|i: int| 0 <= i <= __arg0@.len() implies
        #[trigger] prefix_sum(__arg0@.subrange(0, i)) == sum(first_n(__arg0@, i)) by {
        lemma_prefix_sum_eq_sum_first_n(__arg0@, i);
    }
    if __ret0 {
        let i = choose|i: int| 0 <= i <= __arg0@.len() && #[trigger] prefix_sum(__arg0@.subrange(0, i)) < 0;
        assert(0 <= i <= __arg0@.len() && sum(first_n(__arg0@, i)) < 0);
        assert(exists|j: int| 0 <= j <= __arg0@.len() && #[trigger] sum(first_n(__arg0@, j)) < 0) by {
            assert(0 <= i <= __arg0@.len() && sum(first_n(__arg0@, i)) < 0);
        }
    } else {
        assert forall|j: int| 0 <= j <= __arg0@.len() implies !(#[trigger] sum(first_n(__arg0@, j)) < 0) by {
            assert(prefix_sum(__arg0@.subrange(0, j)) == sum(first_n(__arg0@, j)));
            assert(!(prefix_sum(__arg0@.subrange(0, j)) < 0));
        }
    }
